/**
 * In-memory sample storage, one sorted bucket per series.
 *
 * Deliberately not durable: this is a bounded in-memory buffer over a recent
 * window — nothing is forwarded anywhere, and nothing reads it back.
 */

import type { Sample } from "./validate.ts";

export class MemoryStore {
  private readonly buckets = new Map<string, Sample[]>();
  private readonly maxPerSeries: number;
  private readonly maxSeries: number;
  private readonly retentionMs: number;

  constructor(maxPerSeries: number, maxSeries: number, retentionMs: number) {
    if (!Number.isInteger(maxPerSeries) || maxPerSeries <= 0) {
      throw new RangeError("maxPerSeries must be a positive integer");
    }
    if (!Number.isInteger(maxSeries) || maxSeries <= 0) {
      throw new RangeError("maxSeries must be a positive integer");
    }
    if (!Number.isInteger(retentionMs) || retentionMs <= 0) {
      throw new RangeError("retentionMs must be a positive integer");
    }
    this.maxPerSeries = maxPerSeries;
    this.maxSeries = maxSeries;
    this.retentionMs = retentionMs;
  }

  /**
   * Insert a sample, keeping the series bucket ordered by timestamp.
   *
   * `now` is the caller's wall-clock time of ingestion — supplied, never
   * read from a global, the same way `Router` already supplies `clock.now()`
   * to `parseSample`'s fallback timestamp. It also drives this call's own
   * retention trim (below) — the store ages samples out on its own hot path
   * rather than depending on an external caller to sweep it periodically.
   *
   * An already-tracked series is always admitted, subject to the existing
   * per-series sample cap. A brand-new series is admitted only while the
   * store holds fewer than `maxSeries` distinct series, or by reclaiming one
   * existing series whose entire bucket has already aged past `retentionMs`
   * — an existing series is never evicted while it still holds live data.
   * Returns `false` (and leaves the store unchanged) when a brand-new series
   * is turned away; `true` otherwise.
   */
  put(sample: Sample, now: number): boolean {
    let bucket = this.buckets.get(sample.series);
    if (bucket === undefined) {
      if (this.buckets.size >= this.maxSeries) {
        const expired = this.fullyExpiredSeries(now);
        if (expired === undefined) return false;
        this.buckets.delete(expired);
      }
      bucket = [];
      this.buckets.set(sample.series, bucket);
    }
    const at = insertionPoint(bucket, sample.at);
    bucket.splice(at, 0, sample);
    if (bucket.length > this.maxPerSeries) {
      bucket.splice(0, bucket.length - this.maxPerSeries);
    }
    const expiredPrefix = expiredPrefixLength(bucket, now - this.retentionMs);
    if (expiredPrefix > 0) {
      bucket.splice(0, expiredPrefix);
    }
    if (bucket.length === 0) {
      this.buckets.delete(sample.series);
    }
    return true;
  }

  /**
   * The name of an existing series whose newest sample is already past
   * `retentionMs`, or `undefined` if every series still holds live data.
   */
  private fullyExpiredSeries(now: number): string | undefined {
    const cutoff = now - this.retentionMs;
    for (const [name, bucket] of this.buckets) {
      const newest = bucket[bucket.length - 1];
      if (newest === undefined || newest.at < cutoff) return name;
    }
    return undefined;
  }

  /** Samples for `series` with `from <= at < to`, in timestamp order. */
  range(series: string, from: number, to: number): Sample[] {
    const bucket = this.buckets.get(series);
    if (bucket === undefined) return [];
    return bucket.filter((s) => s.at >= from && s.at < to);
  }

  /** Every series name currently holding at least one sample. */
  series(): string[] {
    return [...this.buckets.keys()].sort();
  }

  /** Drop every sample older than `before`; returns how many were removed. */
  prune(before: number): number {
    let removed = 0;
    for (const [name, bucket] of this.buckets) {
      const keep = bucket.filter((s) => s.at >= before);
      removed += bucket.length - keep.length;
      if (keep.length === 0) {
        this.buckets.delete(name);
      } else {
        this.buckets.set(name, keep);
      }
    }
    return removed;
  }

  size(): number {
    let total = 0;
    for (const bucket of this.buckets.values()) total += bucket.length;
    return total;
  }
}

/** Binary search for the index at which `at` keeps `bucket` sorted. */
function insertionPoint(bucket: Sample[], at: number): number {
  let low = 0;
  let high = bucket.length;
  while (low < high) {
    const mid = (low + high) >>> 1;
    if (bucket[mid].at <= at) low = mid + 1;
    else high = mid;
  }
  return low;
}

