      store.range("a", 0, 100_000).map((s) => s.value),
      [4],
      "the age cap then trimmed both samples that outlived the retention window",
    );
  });
});

describe("MemoryStore per-series cap", () => {
  it("keeps only the newest maxPerSeries samples", () => {
    const store = new MemoryStore(3, 10, 100_000);
    for (let i = 0; i < 10; i++) {
      store.put({ series: "a", value: i, at: i }, i);
    }
    assert.deepEqual(
      store.range("a", 0, 100).map((s) => s.value),
      [7, 8, 9],
    );
  });

  it("rejects a non-positive maxPerSeries", () => {
    assert.throws(() => new MemoryStore(0, 10, 1_000), RangeError);
  });
});

describe("MemoryStore.prune", () => {
  it("drops every sample older than the cutoff and reports the count", () => {
    const store = new MemoryStore(10, 10, 100_000);
    for (let i = 0; i < 5; i++) {
      store.put({ series: "x", value: i, at: i * 1_000 }, i * 1_000);
    }
    const removed = store.prune(3_000);
    assert.equal(removed, 3);
    assert.deepEqual(
      store.range("x", 0, 100_000).map((s) => s.value),
      [3, 4],
    );
  });

  it("removes a series entirely once its bucket is empty", () => {
    const store = new MemoryStore(10, 10, 100_000);
    store.put({ series: "x", value: 1, at: 0 }, 0);
    store.prune(1);
    assert.deepEqual(store.series(), []);
  });
});

