import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { MemoryStore } from "../src/store.ts";

describe("MemoryStore series admission", () => {
  it("admits a new series while under the cap", () => {
    const store = new MemoryStore(10, 2, 100_000);
    assert.equal(store.put({ series: "a", value: 1, at: 0 }, 0), true);
    assert.equal(store.put({ series: "b", value: 1, at: 0 }, 0), true);
    assert.deepEqual(store.series(), ["a", "b"]);
  });

  it("rejects a brand-new series at the cap when nothing is expired", () => {
    const store = new MemoryStore(10, 1, 100_000);
    assert.equal(store.put({ series: "a", value: 1, at: 0 }, 0), true);
    assert.equal(store.put({ series: "b", value: 1, at: 0 }, 0), false);
    assert.deepEqual(store.series(), ["a"]);
  });

  it("reclaims a fully-expired series to admit a new one at the cap", () => {
    const retentionMs = 1_000;
    const store = new MemoryStore(10, 1, retentionMs);
    store.put({ series: "a", value: 1, at: 0 }, 0);

    const admitted = store.put({ series: "b", value: 1, at: 5_000 }, 5_000);

    assert.equal(admitted, true);
    assert.deepEqual(store.series(), ["b"]);
  });

  it("never rejects a put to an already-tracked series", () => {
    const store = new MemoryStore(10, 1, 100_000);
    store.put({ series: "a", value: 1, at: 0 }, 0);
    assert.equal(store.put({ series: "a", value: 2, at: 1 }, 1), true);
    assert.deepEqual(
      store.range("a", 0, 100).map((s) => s.value),
      [1, 2],
    );
  });
});

describe("MemoryStore self-enforced retention", () => {
  it("keeps a sample within the retention window", () => {
    const store = new MemoryStore(10, 10, 1_000);
    store.put({ series: "a", value: 1, at: 0 }, 0);
    store.put({ series: "a", value: 2, at: 500 }, 500);
    assert.deepEqual(
      store.range("a", 0, 100_000).map((s) => s.value),
      [1, 2],
    );
  });

  it("trims a bucket's already-expired samples on every put", () => {
    const store = new MemoryStore(10, 10, 1_000);
    store.put({ series: "a", value: 1, at: 0 }, 0);
    store.put({ series: "a", value: 2, at: 500 }, 500);
    // now=3_000, cutoff=2_000 -- both prior samples (at 0, 500) are stale.
    store.put({ series: "a", value: 3, at: 3_000 }, 3_000);
    assert.deepEqual(
      store.range("a", 0, 100_000).map((s) => s.value),
      [3],
    );
  });

  it("does not retain a sample that is already expired at the moment it is inserted", () => {
    const store = new MemoryStore(10, 10, 1_000);
    const admitted = store.put({ series: "a", value: 1, at: 0 }, 5_000);
    assert.equal(admitted, true, "a well-formed sample is still admitted");
    assert.deepEqual(store.series(), [], "but it is not retained once expired");
  });

  it("applies the count cap and the age cap together on one bucket", () => {
    const store = new MemoryStore(2, 10, 1_000);
    store.put({ series: "a", value: 1, at: 0 }, 0);
    store.put({ series: "a", value: 2, at: 100 }, 100);
    store.put({ series: "a", value: 3, at: 200 }, 200);
    assert.deepEqual(
      store.range("a", 0, 100_000).map((s) => s.value),
      [2, 3],
      "the count cap trimmed the oldest sample",
    );

    store.put({ series: "a", value: 4, at: 5_000 }, 5_000);
    assert.deepEqual(
      store.range("a", 0, 100_000).map((s) => s.value),
      [4],
      "the age cap then trimmed both samples that outlived the retention window",
    );
  });
});

